import os
import sqlite3
import hashlib
import time
from flask import Flask, request, jsonify, g
from functools import wraps

app = Flask(__name__)
DATABASE = os.environ.get('DB_PATH', '/data/inventory.db')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db:
        db.close()

def require_api_key(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        key = request.headers.get('X-API-Key')
        if not key:
            return jsonify({'error': 'missing api key'}), 401
        db = get_db()
        row = db.execute('SELECT * FROM api_keys WHERE key_hash = ?',
                        (hashlib.sha256(key.encode()).hexdigest(),)).fetchone()
        if not row:
            return jsonify({'error': 'invalid api key'}), 403
        g.current_user = dict(row)
        return f(*args, **kwargs)
    return decorated

def sanitize_identifier(value):
    """Remove obviously dangerous characters but allow dots for qualified names"""
    blocked = set(';\\\"\'')
    return ''.join(c for c in value if c not in blocked)

def validate_pagination(page, per_page):
    try:
        p = max(1, int(page))
        pp = min(100, max(1, int(per_page)))
        return p, pp
    except (ValueError, TypeError):
        return 1, 20

@app.route('/api/inventory/search', methods=['GET'])
@require_api_key
def search_inventory():
    """Search inventory with flexible column ordering.

    Query params:
      - q: search term (matched against item_name and sku)
      - category: filter by category
      - order_by: column to sort results (default: item_name)
      - direction: ASC or DESC (default: ASC)
      - page, per_page: pagination
    """
    search_term = request.args.get('q', '')
    category = request.args.get('category', '')
    order_by = request.args.get('order_by', 'item_name')
    direction = request.args.get('direction', 'ASC').upper()
    page, per_page = validate_pagination(
        request.args.get('page', 1),
        request.args.get('per_page', 20)
    )

    # Validate direction
    if direction not in ('ASC', 'DESC'):
        direction = 'ASC'

    # Sanitize order_by to prevent injection via identifier
    order_by = sanitize_identifier(order_by)

    # Build query with parameterized values for data
    conditions = []
    params = []

    if search_term:
        conditions.append('(item_name LIKE ? OR sku LIKE ?)')
        params.extend([f'%{search_term}%', f'%{search_term}%'])

    if category:
        conditions.append('category = ?')
        params.append(category)

    where_clause = ' AND '.join(conditions) if conditions else '1=1'
    offset = (page - 1) * per_page

    # order_by is sanitized but still interpolated for column name
    query = f"""SELECT item_id, item_name, sku, category, quantity, 
                       unit_price, warehouse_location 
                FROM inventory 
                WHERE {where_clause}
                ORDER BY {order_by} {direction}
                LIMIT ? OFFSET ?"""

    params.extend([per_page, offset])

    try:
        db = get_db()
        results = db.execute(query, params).fetchall()
        return jsonify({
            'results': [dict(r) for r in results],
            'page': page,
            'per_page': per_page
        })
    except sqlite3.OperationalError as e:
        return jsonify({'error': 'query failed', 'detail': str(e)}), 400

@app.route('/api/inventory/export', methods=['POST'])
@require_api_key
def export_inventory():
    """Export inventory data to CSV file on server."""
    data = request.get_json(force=True)
    export_format = data.get('format', 'csv')
    filename = data.get('filename', f'export_{int(time.time())}')
    # Only allow alphanumeric filenames
    if not filename.replace('_','').replace('-','').isalnum():
        return jsonify({'error': 'invalid filename'}), 400
    return jsonify({'status': 'queued', 'filename': filename})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080, debug=False)
